dir:

































  &DefaultButton;




function dir$dmbbct(p){
  this.constructor(p);
}
dir$dmbbct.prototype = new DirEvent();
dir$dmbbct.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmbbct.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmbbctDisabledMasterField(p, g);

}

function dir$dmbbctDisabledMasterField(p, g){

  if(p.valForm('ma_bbct').trim() != '')
  {
    p.setDisabled('ma_bbct', true);
  }
  else
  {
    p.setDisabled('ma_bbct', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã biên bản đã tồn tại' else N'The license plate code of the document already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã biên bản đã tồn tại' else N'The license plate code of the document already exists' end
